   $ex${"titre":"Les trois niveaux du grille-pain","competence":"observer-schema","situation":"Le grille-pain de la cuisine dore des tranches de pain. Le schéma va du service rendu au composant concret.","documents":[{"id":"niveaux","type":"chaine","titre":"Du besoin au composant","disposition":"ligne","noeuds":[{"id":"z1","texte":"Griller du pain","emoji":"🍞"},{"id":"z2","texte":"Chauffer","emoji":"🔥"},{"id":"z3","texte":"Résistance chauffante","emoji":"♨️"}],"liens":[{"de":"z1","a":"z2","texte":"se réalise en"},{"de":"z2","a":"z3","texte":"grâce à"}]}],"questions":[{"enonce":"Touche la fonction d’usage du grille-pain.","aide":"C’est le service rendu à l’utilisateur.","type":"zone","document":"niveaux","multiple":false},{"enonce":"Touche la solution technique, le composant concret.","aide":"Cherche l’élément que l’on peut toucher dans l’appareil.","type":"zone","document":"niveaux","multiple":false},{"enonce":"Associe chaque niveau à son exemple pour le grille-pain.","aide":"Le principe technique est le phénomène physique utilisé.","type":"association","gauche":[{"id":"g0","texte":"Fonction d’usage"},{"id":"g1","texte":"Fonction technique"},{"id":"g2","texte":"Principe technique"},{"id":"g3","texte":"Solution technique"}],"droite":[{"id":"d0","texte":"La résistance chauffante"},{"id":"d1","texte":"Griller du pain"},{"id":"d2","texte":"Chauffer"},{"id":"d3","texte":"Un fil parcouru par un courant s’échauffe"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La fonction d’usage est **griller du pain** : le service rendu."},{"cle":{"type":"zone","ids":["z3"]},"explication":"La solution technique est la **résistance chauffante** : c’est le composant concret."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"Service : **griller**. En interne : **chauffer**. Phénomène physique : le fil qui s’échauffe. Composant : la **résistance**."}]$ex$::jsonb),
