   $ex${"titre":"Les mêmes instructions, deux langages","competence":"programmer","situation":"Yanis a écrit un programme en blocs, puis son frère l’a traduit en Python.","documents":[{"id":"blocs","type":"scratch","scripts":[[{"categorie":"evenement","texte":"quand le drapeau vert est cliqué"},{"categorie":"variable","texte":"mettre [ventilateur] à (0)"},{"categorie":"controle","texte":"si (température) > (25) alors","interieur":[{"categorie":"variable","texte":"mettre [ventilateur] à (1)"}],"sinon":[{"categorie":"variable","texte":"mettre [ventilateur] à (0)"}]}]]},{"id":"python","type":"texte","genre":"consigne","titre":"Le même programme en Python","auteur":"Programme écrit pour l’exercice","blocs":["temperature = 30","if temperature > 25 :","    ventilateur = 1","else :","    ventilateur = 0"]}],"questions":[{"enonce":"Associe chaque bloc à sa ligne en Python.","aide":"La condition s’écrit avec « if », l’autre cas avec « else ».","type":"association","gauche":[{"id":"g0","texte":"si (température) > (25) alors"},{"id":"g1","texte":"sinon"},{"id":"g2","texte":"mettre [ventilateur] à (1)"},{"id":"g3","texte":"mettre [ventilateur] à (0)"}],"droite":[{"id":"d0","texte":"else :"},{"id":"d1","texte":"if temperature > 25 :"},{"id":"d2","texte":"ventilateur = 0"},{"id":"d3","texte":"ventilateur = 1"}]},{"enonce":"La température vaut 30. Que vaut ventilateur à la fin ?","aide":"30 est-il supérieur à 25 ?","type":"nombre"},{"enonce":"La température vaut 20. Que vaut ventilateur à la fin ?","aide":"Regarde ce qui se passe quand la condition est fausse.","type":"choix","options":[{"id":"a","texte":"25"},{"id":"b","texte":"0"},{"id":"c","texte":"20"},{"id":"d","texte":"1"}],"multiple":false}]}$ex$::jsonb,
