   $ex${"titre":"Le ventilateur intelligent","competence":"raisonner","situation":"Un ventilateur est piloté par une carte programmable. Le programme lit la température et la présence cinq fois de suite.","documents":[{"id":"prog","type":"texte","genre":"consigne","titre":"Le programme du ventilateur","auteur":"Programme écrit pour l’exercice","blocs":["répéter 5 fois","   lire la température","   lire la présence","   si température > 25 et présence = oui","      allumer le ventilateur","   sinon","      éteindre le ventilateur"]},{"id":"mesures","type":"tableau","titre":"Les cinq mesures","colonnes":["Mesure","1","2","3","4","5"],"lignes":[["Température (°C)",24,27,28,26,22],["Présence","Oui","Oui","Non","Oui","Non"]],"enteteLignes":true,"source":"Situation imaginée pour l’exercice"}],"questions":[{"enonce":"Range chaque élément : entrée ou sortie du programme ?","aide":"Une entrée est lue, une sortie est commandée.","type":"categories","categories":[{"id":"c0","texte":"Entrée"},{"id":"c1","texte":"Sortie"}],"items":[{"id":"i0","texte":"Capteur de présence"},{"id":"i1","texte":"Capteur de température"},{"id":"i2","texte":"Ventilateur"}]},{"enonce":"Sur les cinq mesures, combien de fois le ventilateur est-il allumé ?","aide":"Il faut que les deux conditions soient vraies.","type":"nombre"},{"enonce":"À la mesure 3 (28 °C), le ventilateur reste éteint. Pourquoi ?","aide":"Relis les deux conditions reliées par « et ».","type":"choix","options":[{"id":"a","texte":"Parce que le programme ne lit pas la mesure 3, le capteur étant coupé"},{"id":"b","texte":"Parce que la boucle s’est arrêtée avant d’arriver à la mesure 3"},{"id":"c","texte":"Parce que 28 est inférieur à 25, donc la température est trop basse"},{"id":"d","texte":"Parce que « et » exige aussi la présence, et il n’y a personne"}],"multiple":false},{"enonce":"On remplace « et » par « ou ». Sur les cinq mesures, combien de fois le ventilateur est-il allumé ?","aide":"Avec « ou », une seule condition vraie suffit.","type":"nombre"}]}$ex$::jsonb,
